mapper.insert:
INSERT INTO course_enrollment (
course_id,
student_id,
status
)
VALUES (
#{courseId},
#{studentId},
#{status}
)

mapper.update:
UPDATE course_enrollment
SET
status = #{status},
updated_at = NOW()
WHERE course_id = #{courseId}
AND student_id = #{studentId}

mapper.select:
SELECT ce.enrollment_id, ce.course_id, ce.student_id, a.username, a.full_name, a.email, a.phone, a.avatar, ce.status, ce.enrolled_at FROM course_enrollment ce INNER JOIN account a ON ce.student_id = a.account_id WHERE ce.course_id = #{courseId} AND a.role = 'STUDENT'
AND ce.status = #{status}
ORDER BY ce.enrolled_at DESC

SELECT ce.enrollment_id, c.course_id, c.title, c.description, c.category, c.teacher_id, t.full_name AS teacher_name, c.status AS course_status, ce.status AS enrollment_status, ce.enrolled_at FROM course_enrollment ce INNER JOIN course c ON ce.course_id = c.course_id LEFT JOIN account t ON c.teacher_id = t.account_id WHERE ce.student_id = #{studentId}
AND ce.status = #{status}
ORDER BY ce.enrolled_at DESC
